'use strict';

const fs = require('node:fs');
const path = require('node:path');

const FILE_NAME = 'todos.json';

/** An error caused by bad user input or bad data, as opposed to a bug. */
class TodoError extends Error {
  constructor(message) {
    super(message);
    this.name = 'TodoError';
  }
}

function isTodo(value) {
  return (
    value !== null &&
    typeof value === 'object' &&
    Number.isSafeInteger(value.id) &&
    value.id > 0 &&
    typeof value.text === 'string' &&
    typeof value.completed === 'boolean'
  );
}

/**
 * Reads the todo list from `file`. A missing or blank file is an empty list;
 * anything unparseable is an error, so we never silently overwrite user data.
 */
function loadTodos(file) {
  const name = path.basename(file);
  let raw;
  try {
    raw = fs.readFileSync(file, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') return [];
    throw new TodoError(`Could not read ${name}: ${err.message}`);
  }
  if (raw.trim() === '') return [];

  let data;
  try {
    data = JSON.parse(raw);
  } catch (err) {
    throw new TodoError(`${name} is not valid JSON (${err.message}). Fix or remove the file and try again.`);
  }
  if (!Array.isArray(data) || !data.every(isTodo)) {
    throw new TodoError(`${name} does not contain a valid list of todos. Fix or remove the file and try again.`);
  }
  return data;
}

/** Writes via a temp file + rename so a crash mid-write can't corrupt `file`. */
function saveTodos(file, todos) {
  const tmp = `${file}.${process.pid}.tmp`;
  try {
    fs.writeFileSync(tmp, JSON.stringify(todos, null, 2) + '\n');
    fs.renameSync(tmp, file);
  } catch (err) {
    fs.rmSync(tmp, { force: true });
    throw new TodoError(`Could not write ${path.basename(file)}: ${err.message}`);
  }
}

/** Appends a new todo to `todos` and returns it. */
function addTodo(todos, text, now = new Date()) {
  const trimmed = String(text).trim();
  if (trimmed === '') throw new TodoError('Todo text cannot be empty.');

  const id = todos.reduce((max, todo) => Math.max(max, todo.id), 0) + 1;
  const todo = { id, text: trimmed, completed: false, createdAt: now.toISOString() };
  todos.push(todo);
  return todo;
}

/** Parses a user-supplied id, accepting only positive integers like "3". */
function parseId(input) {
  const str = String(input).trim();
  const id = Number(str);
  if (!/^\d+$/.test(str) || id < 1 || !Number.isSafeInteger(id)) {
    throw new TodoError(`Invalid id "${input}". The id must be a positive integer.`);
  }
  return id;
}

function indexOfId(todos, id) {
  const index = todos.findIndex((todo) => todo.id === id);
  if (index === -1) throw new TodoError(`Todo #${id} not found.`);
  return index;
}

/** Marks the todo done. Returns it plus whether it was already done. */
function completeTodo(todos, id) {
  const todo = todos[indexOfId(todos, id)];
  const alreadyCompleted = todo.completed;
  todo.completed = true;
  return { todo, alreadyCompleted };
}

/** Removes the todo from `todos` and returns it. */
function deleteTodo(todos, id) {
  return todos.splice(indexOfId(todos, id), 1)[0];
}

/** One line per todo: "<id>. [x] <text>", ids right-aligned. */
function formatTodos(todos) {
  const width = Math.max(...todos.map((todo) => String(todo.id).length));
  return todos
    .map((todo) => `${String(todo.id).padStart(width)}. [${todo.completed ? 'x' : ' '}] ${todo.text}`)
    .join('\n');
}

module.exports = {
  FILE_NAME,
  TodoError,
  loadTodos,
  saveTodos,
  addTodo,
  parseId,
  completeTodo,
  deleteTodo,
  formatTodos,
};
# cli-todo-app

A small command-line todo app for Node.js (18+), with no dependencies.

```sh
node index.js add "Buy groceries"   # Added todo #1: Buy groceries
node index.js list                  # 1. [ ] Buy groceries
node index.js complete 1            # Completed todo #1: Buy groceries
node index.js delete 1              # Deleted todo #1: Buy groceries
node index.js help
```

Todos are saved in `todos.json` in the directory you run the command from, so each directory has its own list. Each todo looks like this:

```json
{ "id": 1, "text": "Buy groceries", "completed": false, "createdAt": "2026-09-30T12:00:00.000Z" }
```

## Behavior notes

- A new todo's id is one more than the highest existing id. Gaps left by deletions are not filled.
- `add Buy groceries` (without quotes) also works: the words are joined into one todo.
- Errors (missing arguments, invalid or unknown ids, unknown commands, a corrupt `todos.json`) go to stderr with exit code 1. A corrupt file is never overwritten.
- Completing a todo that is already done is not an error.

## Tests

```sh
npm test
```

`test/todos.test.js` unit-tests the storage and todo operations. `test/cli.test.js` runs `node index.js` end-to-end in temporary directories.
'use strict';

// End-to-end tests: each one runs the real `node index.js` in a fresh temp
// directory, so todos.json is created relative to the process's cwd.

const { describe, it, beforeEach, afterEach } = require('node:test');
const assert = require('node:assert/strict');
const { spawnSync } = require('node:child_process');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

const INDEX = path.join(__dirname, '..', 'index.js');

let cwd;
let file;

function run(...args) {
  const result = spawnSync(process.execPath, [INDEX, ...args], { cwd, encoding: 'utf8' });
  return { code: result.status, stdout: result.stdout, stderr: result.stderr };
}

function readTodos() {
  return JSON.parse(fs.readFileSync(file, 'utf8'));
}

function writeRaw(contents) {
  fs.writeFileSync(file, contents);
}

function assertFails(result, messagePattern) {
  assert.equal(result.code, 1, `expected exit code 1, got ${result.code}`);
  assert.equal(result.stdout, '');
  assert.match(result.stderr, /^Error: /);
  assert.match(result.stderr, messagePattern);
}

beforeEach(() => {
  cwd = fs.mkdtempSync(path.join(os.tmpdir(), 'todo-cli-'));
  file = path.join(cwd, 'todos.json');
});

afterEach(() => {
  fs.rmSync(cwd, { recursive: true, force: true });
});

describe('add', () => {
  it('creates todos.json in the current directory with the new todo', () => {
    const before = Date.now();
    const result = run('add', 'Buy groceries');
    const after = Date.now();

    assert.equal(result.code, 0);
    assert.equal(result.stdout, 'Added todo #1: Buy groceries\n');
    assert.equal(result.stderr, '');

    const todos = readTodos();
    assert.equal(todos.length, 1);
    const [{ id, text, completed, createdAt, ...rest }] = todos;
    assert.equal(id, 1);
    assert.equal(text, 'Buy groceries');
    assert.equal(completed, false);
    assert.equal(new Date(createdAt).toISOString(), createdAt, 'createdAt should be an ISO timestamp');
    assert.ok(Date.parse(createdAt) >= before && Date.parse(createdAt) <= after);
    assert.deepEqual(rest, {}, 'no unexpected fields');
  });

  it('assigns auto-incrementing ids', () => {
    run('add', 'First');
    run('add', 'Second');
    const result = run('add', 'Third');

    assert.equal(result.stdout, 'Added todo #3: Third\n');
    assert.deepEqual(readTodos().map((t) => [t.id, t.text]), [
      [1, 'First'],
      [2, 'Second'],
      [3, 'Third'],
    ]);
  });

  it('does not reuse the id of a deleted todo in the middle of the list', () => {
    run('add', 'a');
    run('add', 'b');
    run('add', 'c');
    run('delete', '2');
    run('add', 'd');

    assert.deepEqual(readTodos().map((t) => t.id), [1, 3, 4]);
  });

  it('joins unquoted words into a single todo', () => {
    const result = run('add', 'Buy', 'groceries', 'today');
    assert.equal(result.stdout, 'Added todo #1: Buy groceries today\n');
    assert.equal(readTodos()[0].text, 'Buy groceries today');
  });

  it('trims surrounding whitespace and keeps special characters intact', () => {
    run('add', '  Email "Bob" re: 50% off & <stuff> ✅  ');
    assert.equal(readTodos()[0].text, 'Email "Bob" re: 50% off & <stuff> ✅');
  });

  it('fails without text and does not create todos.json', () => {
    assertFails(run('add'), /Missing todo text/);
    assert.equal(fs.existsSync(file), false);
  });

  it('fails when the text is empty or only whitespace', () => {
    assertFails(run('add', ''), /cannot be empty/);
    assertFails(run('add', '   '), /cannot be empty/);
    assert.equal(fs.existsSync(file), false);
  });
});

describe('list', () => {
  it('reports an empty list when todos.json does not exist', () => {
    const result = run('list');
    assert.equal(result.code, 0);
    assert.match(result.stdout, /^No todos yet\./);
    assert.equal(result.stderr, '');
    assert.equal(fs.existsSync(file), false, 'listing should not create the file');
  });

  it('reports an empty list when todos.json holds an empty array', () => {
    writeRaw('[]');
    const result = run('list');
    assert.equal(result.code, 0);
    assert.match(result.stdout, /^No todos yet\./);
  });

  it('shows id, status indicator, and text for each todo in order', () => {
    run('add', 'Buy groceries');
    run('add', 'Walk the dog');
    run('add', 'Read a book');
    run('complete', '2');

    const result = run('list');
    assert.equal(result.code, 0);
    assert.equal(result.stdout, '1. [ ] Buy groceries\n2. [x] Walk the dog\n3. [ ] Read a book\n');
    assert.equal(result.stderr, '');
  });

  it('reflects deletions', () => {
    run('add', 'Keep');
    run('add', 'Remove');
    run('delete', '2');
    assert.equal(run('list').stdout, '1. [ ] Keep\n');
  });

  it('reports an empty list after the last todo is deleted', () => {
    run('add', 'Only one');
    run('delete', '1');
    assert.match(run('list').stdout, /^No todos yet\./);
    assert.deepEqual(readTodos(), []);
  });
});

describe('complete', () => {
  beforeEach(() => {
    run('add', 'Buy groceries');
    run('add', 'Walk the dog');
  });

  it('marks the todo as done and leaves others untouched', () => {
    const before = readTodos();
    const result = run('complete', '1');

    assert.equal(result.code, 0);
    assert.equal(result.stdout, 'Completed todo #1: Buy groceries\n');
    assert.equal(result.stderr, '');
    assert.deepEqual(readTodos(), [{ ...before[0], completed: true }, before[1]]);
  });

  it('succeeds without changes when the todo is already done', () => {
    run('complete', '1');
    const before = fs.readFileSync(file, 'utf8');
    const result = run('complete', '1');

    assert.equal(result.code, 0);
    assert.equal(result.stdout, 'Todo #1 is already completed: Buy groceries\n');
    assert.equal(fs.readFileSync(file, 'utf8'), before);
  });

  it('fails without an id', () => {
    assertFails(run('complete'), /Missing todo id\. Usage: node index\.js complete <id>/);
  });

  for (const id of ['abc', '0', '-1', '1.5', '']) {
    it(`fails for invalid id ${JSON.stringify(id)}`, () => {
      const before = fs.readFileSync(file, 'utf8');
      assertFails(run('complete', id), /Invalid id/);
      assert.equal(fs.readFileSync(file, 'utf8'), before);
    });
  }

  it('fails for an id that does not exist', () => {
    const before = fs.readFileSync(file, 'utf8');
    assertFails(run('complete', '99'), /Todo #99 not found/);
    assert.equal(fs.readFileSync(file, 'utf8'), before);
  });

  it('fails with more than one id rather than silently ignoring extras', () => {
    assertFails(run('complete', '1', '2'), /Too many arguments/);
    assert.ok(readTodos().every((t) => !t.completed));
  });

  it('fails for any id when there are no todos', () => {
    fs.rmSync(file);
    assertFails(run('complete', '1'), /Todo #1 not found/);
  });
});

describe('delete', () => {
  beforeEach(() => {
    run('add', 'Buy groceries');
    run('add', 'Walk the dog');
  });

  it('removes the todo', () => {
    const before = readTodos();
    const result = run('delete', '1');

    assert.equal(result.code, 0);
    assert.equal(result.stdout, 'Deleted todo #1: Buy groceries\n');
    assert.equal(result.stderr, '');
    assert.deepEqual(readTodos(), [before[1]]);
  });

  it('can delete a completed todo', () => {
    run('complete', '2');
    assert.equal(run('delete', '2').code, 0);
    assert.deepEqual(readTodos().map((t) => t.id), [1]);
  });

  it('fails when deleting the same todo twice', () => {
    run('delete', '1');
    assertFails(run('delete', '1'), /Todo #1 not found/);
  });

  it('fails without an id', () => {
    assertFails(run('delete'), /Missing todo id\. Usage: node index\.js delete <id>/);
  });

  for (const id of ['abc', '0', '-1', '1.5', '']) {
    it(`fails for invalid id ${JSON.stringify(id)}`, () => {
      const before = fs.readFileSync(file, 'utf8');
      assertFails(run('delete', id), /Invalid id/);
      assert.equal(fs.readFileSync(file, 'utf8'), before);
    });
  }

  it('fails for an id that does not exist', () => {
    const before = fs.readFileSync(file, 'utf8');
    assertFails(run('delete', '99'), /Todo #99 not found/);
    assert.equal(fs.readFileSync(file, 'utf8'), before);
  });

  it('fails with more than one id rather than silently ignoring extras', () => {
    assertFails(run('delete', '1', '2'), /Too many arguments/);
    assert.equal(readTodos().length, 2);
  });
});

describe('commands and usage', () => {
  it('prints usage and fails when no command is given', () => {
    const result = run();
    assertFails(result, /Missing command/);
    assert.match(result.stderr, /Usage:/);
  });

  it('prints usage and fails for an unknown command', () => {
    const result = run('remove', '1');
    assertFails(result, /Unknown command "remove"/);
    assert.match(result.stderr, /Usage:/);
  });

  for (const flag of ['help', '--help', '-h']) {
    it(`prints usage for "${flag}"`, () => {
      const result = run(flag);
      assert.equal(result.code, 0);
      assert.match(result.stdout, /^Usage:/);
      for (const command of ['add', 'list', 'complete', 'delete']) {
        assert.match(result.stdout, new RegExp(`node index\\.js ${command}`));
      }
      assert.equal(result.stderr, '');
    });
  }

  it('treats command names case-sensitively', () => {
    assertFails(run('LIST'), /Unknown command "LIST"/);
  });
});

describe('storage', () => {
  it('uses todos.json in the current directory, not next to index.js', () => {
    const appFile = path.join(path.dirname(INDEX), 'todos.json');
